@pytest.mark.parametrize("cp_id", sorted(CODEPAGE_PREFIX_8.keys()))
def test_codepage_prefix_8_chars(cp_id):
    bytes_str = ",".join(str(b) for b in range(128, 256))
    bin_expr = f"#binary({{{bytes_str}}})"
    probe = f"Csv.Document({bin_expr}, null, null, null, {cp_id})"
    expected_8 = CODEPAGE_PREFIX_8[cp_id]
    prefix = evaluate_to_text(f"Text.Start(Table.ToRows({probe}){{0}}{{0}}, 8)")
    assert prefix == f'V:text:"{expected_8}"'

