@pytest.mark.parametrize('pid,probe,answer', PAIRS_R6, ids=[p[0] for p in PAIRS_R6])
def test_pairs_r6(pid, probe, answer):
    res = evaluate_to_text(probe)
    assert res == answer


@pytest.mark.parametrize('pid,probe,answer', EITHER_R6, ids=[p[0] for p in EITHER_R6])
def test_either_r6(pid, probe, answer):
    res = evaluate_to_text(probe)
    if 'is not supported by this engine yet' in res:
        return
    assert res == answer


