@pytest.mark.parametrize('pid,probe,answer', PAIRS_R7, ids=[p[0] for p in PAIRS_R7])
def test_pairs_r7(pid, probe, answer):
    res = evaluate_to_text(probe)
    assert res == answer


@pytest.mark.parametrize('pid,probe,answer', EITHER_R7, ids=[p[0] for p in EITHER_R7])
def test_either_r7(pid, probe, answer):
    res = evaluate_to_text(probe)
    if 'is not supported by this engine yet' in res:
        return
    assert res == answer


