@pytest.mark.parametrize('pid,probe,answer', EITHER_R8, ids=[p[0] for p in EITHER_R8])
def test_either_r8(pid, probe, answer):
    res = evaluate_to_text(probe)
    if 'is not supported by this engine yet' in res:
        return
    assert res == answer


