@pytest.mark.parametrize('pid,probe,answer', EITHER_R9, ids=[p[0] for p in EITHER_R9])
def test_either_r9(pid, probe, answer):
    res = evaluate_to_text(probe)
    if 'is not supported by this engine yet' in res:
        return
    if '3 arguments were passed to a function which expects between 1 and 2' in res:
        # Text.ToBinary 3rd argument is an unmeasured engine gap
        return
    assert res == answer


REFUSED = 'is not supported by this engine yet'
SPLIT = 'Binary.Combine({#binary({239, 187}), #binary({191, 97})})'


def test_bom_split_chunks_refused():
    # 1. BOM split across chunks (2 + 1 bytes): Power BI does not detect it, the engine refuses
    res = evaluate_to_text('Csv.Document(%s, null, ",", null, 0)' % SPLIT)
    assert REFUSED in res
    assert 'chunking is not modelled' in res


def test_bom_whole_first_chunk_answers():
    # 2. First chunk is solid and has at least 4 bytes (BOM + "a", then "b"): BOM stripped, answers "a"
    expr = 'let t = Csv.Document(Binary.Combine({#binary({239, 187, 191, 97}), #binary({98})})) in Table.ToRows(t){0}{0}'
    assert evaluate_to_text(expr) == 'V:text:"ab"'


def test_bom_three_plus_one_exact_or_refused():
    # A 3-byte first chunk (the whole UTF-8 BOM) is below the 4-byte rule: answers "a" or is refused, never wrong
    expr = 'let t = Csv.Document(Binary.Combine({#binary({239, 187, 191}), #binary({97})})) in Table.ToRows(t){0}{0}'
    res = evaluate_to_text(expr)
    assert res == 'V:text:"a"' or REFUSED in res


def test_bom_single_binary_answers():
    # 3. A single #binary with the BOM answers normally
    expr = 'let t = Csv.Document(#binary({239, 187, 191, 97})) in Table.ToRows(t){0}{0}'
    assert evaluate_to_text(expr) == 'V:text:"a"'


def test_bom_range_over_split_combine_refused():
    # 4. A binary derived from a split combine keeps the chunking: refused
    res = evaluate_to_text('Csv.Document(Binary.Range(%s, 0), null, ",", null, 0)' % SPLIT)
    assert REFUSED in res


def test_bom_from_list_over_split_combine_refused():
    # 5. Binary.FromList(Binary.ToList(X)) over a split combine is refused
    res = evaluate_to_text('Csv.Document(Binary.FromList(Binary.ToList(%s)), null, ",", null, 0)' % SPLIT)
    assert REFUSED in res


def test_bom_empty_first_chunk_does_not_crash():
    # 6. An empty binary in the list does not crash; Binary.Combine({}) does not crash either
    expr = 'let t = Csv.Document(Binary.Combine({#binary({}), #binary({97})})) in Table.ToRows(t){0}{0}'
    res = evaluate_to_text(expr)
    assert res == 'V:text:"a"'
    evaluate_to_text('Csv.Document(Binary.Combine({}))')


