@pytest.mark.parametrize('pid,probe,answer', EITHER_R10, ids=[p[0] for p in EITHER_R10])
def test_either_r10(pid, probe, answer):
    res = evaluate_to_text(probe)
    if 'is not supported by this engine yet' in res:
        return
    if '3 arguments were passed to a function which expects between 1 and 2' in res:
        # Text.ToBinary 3rd argument is an unmeasured engine gap
        return
    assert res == answer
